import{_ as t,o as n,a,ag as i}from"./chunks/framework.1whTfjCw.js";const o="/assets/index-hero.C7kgN8bw.gif",p=JSON.parse('{"title":"tnk 0.1.36 (experimental)","description":"","frontmatter":{},"headers":[],"relativePath":"tnk/index.md","filePath":"tnk/index.md","lastUpdated":1785259870000}'),s={name:"tnk/index.md"};function r(l,e,d,c,h,u){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="tnk-0-1-36-experimental" tabindex="-1">tnk 0.1.36 (experimental) <a class="header-anchor" href="#tnk-0-1-36-experimental" aria-label="Permalink to &quot;tnk __TNK_VERSION__ (experimental)&quot;">​</a></h1><p>tnk is a zero-trust sandbox for local inference and AI agent runtimes. It manages the inference engine on the host and per-project Lima sandboxes with isolated execution environments.</p><img src="'+o+'" alt="tnk CLI demo" width="100%"><p>tnk follows Unix design principles:</p><ul><li>subcommands grouped by lifecycle domain</li><li>scriptable output (<code>text</code>, <code>json</code>, <code>ndjson</code>)</li><li>explicit defaults you must override intentionally</li><li>safe behavior when context is missing</li></ul><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>Agent stacks execute package installers, shell commands, generated scripts, and network clients with broad filesystem access. A compromised dependency gives an attacker access to your credentials, keys, and system files.</p><p>tnk reduces that risk through enforced boundaries:</p><ul><li>run agent execution inside Lima VM sandboxes</li><li>keep host-only assets outside sandbox mounts</li><li>gate runtime context with explicit env contracts</li><li>log every sandbox session for audit and incident review</li></ul><h2 id="core-model" tabindex="-1">Core model <a class="header-anchor" href="#core-model" aria-label="Permalink to &quot;Core model&quot;">​</a></h2><ol><li><strong>Host inference engine</strong> — managed by <code>tnk engine</code></li><li><strong>Per-project sandbox</strong> — Lima VMs for isolated execution, managed by <code>tnk sandbox</code></li></ol><p>The default path is <code>tnk run</code> — it boots the inference engine, then you enter project sandboxes as needed.</p><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><ol><li><a href="/tnk/quickstart">Quickstart</a></li><li><a href="/tnk/commands">Commands</a></li><li><a href="/tnk/sandbox">Sandbox</a></li><li><a href="/tnk/security">Security</a></li><li><a href="/tnk/configuration">Configuration</a></li></ol><hr><p><strong>See also:</strong> <a href="/tnk/quickstart">Quickstart</a> · <a href="/tnk/concepts">Concepts</a> · <a href="/tnk/security">Security</a></p>',16)])])}const x=t(s,[["render",r]]);export{p as __pageData,x as default};
